<template><section class="social-page community"><header class="community-head"><button v-if="thread" @click="thread=null">‹ 목록</button><h1>{{thread?'게시글':'커뮤니티'}}</h1><button v-if="!thread" class="primary" @click="editor.showModal()">글쓰기</button></header><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
<template v-if="!thread"><div class="social-tabs"><button v-for="c in categories" :key="c[0]" :class="{selected:category===c[0]}" @click="category=c[0];load()">{{c[1]}}</button></div><p v-if="!posts.length&&!busy" class="social-empty">첫 이야기를 나눠보세요.</p><button class="post-preview" v-for="p in posts" :key="p.id" @click="open(p.id)"><small>{{label(p.category)}} · {{p.author}}</small><h2>{{p.title}}</h2><p>{{p.body.slice(0,100)}}</p><time>{{date(p.createdAt)}}</time></button><button v-if="more" :disabled="busy" @click="load(true)">더 보기</button></template>
<template v-else><article class="post-detail"><small>{{label(thread.post.category)}} · {{thread.post.author}}</small><h2>{{thread.post.title}}</h2><p>{{thread.post.body}}</p><time>{{date(thread.post.createdAt)}}</time><button @click="thread.post.mine?remove(thread.post):report(thread.post)">{{thread.post.mine?'삭제':'신고'}}</button></article><h2>댓글</h2><p v-if="!thread.comments.length">첫 댓글을 남겨보세요.</p><article v-for="p in thread.comments" :key="p.id" class="comment"><strong>{{p.author}}</strong><p>{{p.body}}</p><time>{{date(p.createdAt)}}</time><button @click="p.mine?remove(p):report(p)">{{p.mine?'삭제':'신고'}}</button></article><small v-if="thread.comments.length===50">최근 댓글 50개를 표시합니다.</small><form @submit.prevent="reply"><textarea v-model="comment" maxlength="3000" required placeholder="따뜻한 조언을 남겨주세요" aria-label="댓글"/><button class="primary" :disabled="busy||!comment.trim()">댓글 등록</button></form></template>
<dialog ref="editor" class="social-dialog" @cancel="busy&&$event.preventDefault()"><h2>이야기 나누기</h2><form @submit.prevent="create"><select v-model="form.category" aria-label="게시판"><option v-for="c in categories.slice(1)" :value="c[0]">{{c[1]}}</option></select><input v-model="form.title" maxlength="80" required placeholder="제목" aria-label="제목"/><textarea v-model="form.body" maxlength="3000" required placeholder="어떤 이야기를 나누고 싶나요?" aria-label="내용"/><p>연락처·개인정보와 금전 거래를 유도하는 내용은 올리지 말아 주세요.</p><p v-if="error" role="alert">{{error}}</p><button type="button" :disabled="busy" @click="editor.close()">취소</button><button class="primary" :disabled="busy">등록</button></form></dialog></section></template>
<script setup>
import {ref,onMounted} from 'vue';import api from '../../api/api';import '../../components/social.css';
const posts=ref([]),thread=ref(null),editor=ref(),category=ref('ALL'),busy=ref(false),more=ref(false),error=ref(''),notice=ref(''),comment=ref(''),form=ref({category:'ADVICE',title:'',body:''});const categories=[['ALL','전체'],['ADVICE','고민 상담'],['DATING','연애 이야기'],['DAILY','일상']];const label=v=>categories.find(c=>c[0]===v)?.[1];const date=v=>new Date(v).toLocaleString('ko-KR');let seq=0;
async function load(append=false){const id=++seq;busy.value=true;error.value='';try{const {data}=await api.get('/community',{params:{category:category.value,before:append?posts.value.at(-1)?.id:0}});if(id!==seq)return;posts.value=append?[...posts.value,...data]:data;more.value=data.length===20;}catch(e){error.value=e.response?.data?.message||'목록을 불러오지 못했어요.';}finally{if(id===seq)busy.value=false;}}
async function open(id){error.value='';try{thread.value=(await api.get(`/community/${id}`)).data;comment.value='';}catch(e){error.value=e.response?.data?.message||'게시글을 불러오지 못했어요.';}}
async function create(){if(busy.value)return;busy.value=true;error.value='';try{const {data}=await api.post('/community',form.value);editor.value.close();form.value={category:'ADVICE',title:'',body:''};await load();await open(data.id);}catch(e){error.value=e.response?.data?.message||'등록하지 못했어요.';}finally{busy.value=false;}}
async function reply(){if(busy.value)return;busy.value=true;error.value='';try{const text=comment.value;await api.post('/community',{parentId:thread.value.post.id,body:text});await open(thread.value.post.id);}catch(e){error.value=e.response?.data?.message||'댓글을 등록하지 못했어요.';}finally{busy.value=false;}}
async function remove(p){if(!confirm('삭제할까요?'))return;try{await api.delete(`/community/${p.id}`);if(p.parentId)await open(p.parentId);else{thread.value=null;await load();}}catch(e){error.value=e.response?.data?.message||'삭제하지 못했어요.';}}
async function report(p){const reason=prompt('신고 사유를 입력해 주세요.');if(!reason)return;try{await api.post(`/community/${p.id}/report`,{reason});notice.value='게시글 신고를 접수했어요. 운영자가 확인할게요.';}catch(e){error.value=e.response?.data?.message||'신고하지 못했어요.';}}
onMounted(()=>load());
</script><style scoped>.community-head{padding-right:48px;display:flex;align-items:center;gap:12px}.community-head h1{flex:1}.post-preview{display:block;width:100%;border:0;border-bottom:1px solid #eee;background:white;text-align:left;padding:20px 8px}.post-preview h2,.post-detail h2{font-size:18px;margin:9px 0}.post-preview p{margin:0 0 12px;color:#785f53}.community small,.community time{font-size:11px;color:#967b6c}.post-detail,.comment{padding:20px 0;border-bottom:1px solid #efdfd3}.post-detail p,.comment p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.7}.post-detail button,.comment button{float:right}.community textarea{box-sizing:border-box;width:100%;min-height:110px;border:1px solid #e5c8ba;border-radius:12px;padding:12px;margin:12px 0;font:inherit}.community input,.community select{box-sizing:border-box;width:100%;padding:12px;margin:8px 0;border:1px solid #e5c8ba;border-radius:10px}.social-dialog p{font-size:12px;line-height:1.6}</style>
